function addIncoming(){const tabs=document.querySelector(".tabs");if(!tabs||document.getElementById("incoming"))return;const btn=document.createElement("button");btn.className="tab";btn.dataset.tab="incoming";btn.textContent="Próximos ingresos";tabs.appendChild(btn);const sec=document.createElement("section");sec.id="incoming";sec.className="panel";sec.innerHTML=`<div class="topline"><div><h2>Radar de próximos ingresos</h2><p>Sube el Excel de mercadería por llegar. Muestra únicamente SKU sin stock actual que vienen en camino y clientes que los compran de forma recurrente. Incluye cuánto compró antes cada cliente.</p></div></div><div class="v10upload"><input id="incomingFile" type="file" accept=".xlsx,.xls"><button class="primary" id="incomingRead">Leer Excel</button><button class="soft" id="incomingClear">Limpiar ingresos</button><div id="incomingPreview" class="note">No se reemplaza el stock actual. Esta carga es una capa comercial separada.</div></div><div class="incomingTools"><div class="segmented"><button class="active" data-inview="client">Por cliente</button><button data-inview="sku">Por SKU</button></div><input id="incomingSearch" placeholder="Filtrar por cliente, SKU o producto"></div><div class="kpis" id="incomingKpis"></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>SKU / producto</th><th>Por llegar</th><th>Fecha estimada</th><th>Compras anteriores</th><th>Estado</th></tr></thead><tbody id="incomingRows"></tbody></table></div></section>`;document.querySelector("main")?.appendChild(sec)||tabs.parentNode.appendChild(sec);btn.onclick=()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));btn.classList.add("active");sec.classList.add("active");renderIncoming()};sec.querySelectorAll("[data-inview]").forEach(v=>v.onclick=()=>{incomingView=v.dataset.inview;sec.querySelectorAll("[data-inview]").forEach(x=>x.classList.toggle("active",x===v));renderIncoming()});document.getElementById("incomingSearch").oninput=e=>{incomingQuery=e.target.value;renderIncoming()};document.getElementById("incomingRead").onclick=readExcel;document.getElementById("incomingClear").onclick=()=>{if(confirm("¿Limpiar la mercadería por llegar cargada?")){incoming=[];localStorage.removeItem(KEY);renderIncoming()}};renderIncoming()}
function readExcel(){const f=document.getElementById("incomingFile")?.files?.[0],pv=document.getElementById("incomingPreview");if(!f)return pv.textContent="Selecciona un Excel.";if(typeof XLSX==="undefined")return pv.textContent="El lector Excel no cargó. Recarga la página e intenta nuevamente.";const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(r.result,{type:"array",cellDates:true});let rows=[];for(const sh of wb.SheetNames){const x=XLSX.utils.sheet_to_json(wb.Sheets[sh],{defval:""});if(x.length){rows=x;break}}const mapped=rows.map((x,i)=>({sku:String(getCol(x,["sku","codigo","código"])).trim(),qty:+String(getCol(x,["cantidad","qty","unidades"])).replace(/[^0-9.-]/g,"")||0,eta:excelDate(getCol(x,["fecha estimada","fecha llegada","eta","llegada","arribo"])),product:String(getCol(x,["producto","nombre","descripcion","descripción"])).trim(),row:i+2})).filter(x=>x.sku);if(!mapped.length)throw Error("No encontré una columna SKU/Código.");const map=new Map(incoming.map(x=>[norm(x.sku),x]));mapped.forEach(x=>map.set(norm(x.sku),{...(map.get(norm(x.sku))||{}),...x,updatedAt:new Date().toISOString()}));incoming=[...map.values()];localStorage.setItem(KEY,JSON.stringify(incoming));pv.innerHTML=`<b>${mapped.length} SKU leídos</b> · ${mapped.reduce((s,x)=>s+x.qty,0)} unidades. Se cruzaron con el historial B2B.`;renderIncoming()}catch(e){pv.textContent="No pude leer el Excel: "+e.message}};r.readAsArrayBuffer(f)}
function injectWaitingIntoClient(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.waitObserver)return;panel.dataset.waitObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;const txt=detail.innerText||"";if(!panel.classList.contains("open")&&getComputedStyle(panel).display==="none")return;if(detail.querySelector(".waitSkuBox"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const box=document.createElement("div");box.className="waitSkuBox";box.innerHTML='<h3>Cliente esperando SKU</h3><p>Registra un producto que este cliente pidió aunque hoy no tenga stock. Cuando aparezca en Próximos ingresos quedará como prioridad.</p><input class="waitSku" placeholder="SKU"><input class="waitProduct" placeholder="Producto (opcional)"><input class="waitNote" placeholder="Nota (opcional)"><button class="primary">Marcar como esperando</button><div class="waitList"></div>';detail.appendChild(box);const draw=()=>{box.querySelector(".waitList").innerHTML=waiting.filter(w=>w.clientId==c.id&&w.active!==false).map(w=>`<div><b>${esc(w.sku)}</b> ${esc(w.product||"")} <button class="miniDone" data-sku="${esc(w.sku)}">Resolver</button></div>`).join("")||"<small>Sin SKU pendientes.</small>";box.querySelectorAll(".miniDone").forEach(b=>b.onclick=()=>{clearWaiting(c.id,b.dataset.sku);draw()})};box.querySelector(".primary").onclick=()=>{const sku=box.querySelector(".waitSku").value.trim();if(!sku)return alert("Ingresa el SKU.");setWaiting(c.id,sku,box.querySelector(".waitProduct").value,box.querySelector(".waitNote").value);box.querySelector(".waitSku").value="";box.querySelector(".waitProduct").value="";box.querySelector(".waitNote").value="";draw()};draw()}).observe(panel,{childList:true,subtree:true})}
const STAGES=["Detectado","Contactado","Respondió","Oportunidad","Propuesta","Pedido","Recompra"];
function pipeOf(id){return pipeline[id]||{stage:"Detectado",amount:0,updatedAt:""}}
