function setStage(id,stage,amount=0){pipeline[id]={...pipeOf(id),stage,amount:+amount||pipeOf(id).amount||0,updatedAt:new Date().toISOString()};savePipe();renderPipeline();renderMvpDashboard()}
function renderPipeline(){const host=document.getElementById("mvpPipeline");if(!host)return;const cs=state?.clients||[];host.innerHTML=STAGES.map(st=>{const ids=cs.filter(c=>pipeOf(c.id).stage===st);const amount=ids.reduce((a,c)=>a+(+pipeOf(c.id).amount||0),0);return `<div class="pipeStage"><small>${st}</small><b>${ids.length}</b><span>${st==="Pedido"||st==="Recompra"?new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(amount):"clientes"}</span></div>`}).join("")}
function renderMvpDashboard(){const host=document.getElementById("mvpDash");if(!host)return;const cs=state?.clients||[],today=new Date(),active=cs.filter(c=>{const d=ds(getLast(c));return d!=null&&d<=90}).length,risk=cs.filter(c=>clientPriority(c).p==="P1").length,won=Object.values(pipeline).filter(x=>["Pedido","Recompra"].includes(x.stage)).reduce((a,x)=>a+(+x.amount||0),0),managed=Object.keys(pipeline).filter(id=>pipeOf(id).stage!=="Detectado").length;host.innerHTML=[["Cartera",cs.length],["Activos ≤90d",active],["En riesgo/P1",risk],["Gestionados",managed],["$ CRM",new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(won)]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("")}
function addMvpDashboard(){const hoy=document.getElementById("hoy");if(!hoy||document.getElementById("mvpDashWrap"))return;const w=document.createElement("div");w.id="mvpDashWrap";w.className="mvpDashWrap";w.innerHTML='<div class="mvpTitle"><small>CONTROL COMERCIAL</small><h2>Dashboard MVP</h2></div><div id="mvpDash" class="kpis"></div><h3>Pipeline</h3><div id="mvpPipeline" class="pipelineMvp"></div>';const anchor=document.getElementById("mvpToday");anchor?anchor.after(w):hoy.prepend(w);renderMvpDashboard();renderPipeline()}
function saveActions(){localStorage.setItem(TASK_KEY,JSON.stringify(nextActions))}
function addNextAction(clientId,type,date,note){if(!date)return alert("Selecciona la fecha de próxima acción.");nextActions.unshift({id:(crypto.randomUUID?crypto.randomUUID():Date.now()+"-"+Math.random()),clientId,type:type||"Seguimiento",date,note:note||"",done:false,createdAt:new Date().toISOString()});saveActions();renderTodayMVP();}
function completeAction(id){const x=nextActions.find(a=>a.id===id);if(x){x.done=true;x.doneAt=new Date().toISOString();saveActions();renderTodayMVP()}}
function clientName(c){return c?.cliente||c?.contacto||c?.nombre||c?.email||"Cliente"}
function ds(d){if(!d)return null;return Math.floor((Date.now()-new Date(d).getTime())/86400000)}
function getLast(c){return c.ultimaB2B||c.ultima||c.lastPurchase||c.ultimaCompra||""}
function getCycle(c){return +(c.reorderMedian||c.reorderDays||c.ciclo||c.cycle||0)}
function clientPriority(c){const d=ds(getLast(c)),cy=getCycle(c);if((c.b2bConfirmedOrders||c.pedidos||c.orders||0)===1)return{p:"P1",why:"Activar segunda compra",score:95};if(d!=null&&cy&&d>cy*1.25)return{p:"P1",why:`Recompra atrasada ${Math.max(0,d-cy)} días`,score:90};if(d!=null&&cy&&d>cy*.85)return{p:"P2",why:"Entrando en ventana de recompra",score:70};return{p:"P3",why:"Seguimiento preventivo",score:40}}
function dueActions(){const today=new Date().toISOString().slice(0,10);return nextActions.filter(x=>!x.done&&x.date<=today)}
function buildToday(){const due=dueActions(),ids=new Set(due.map(x=>String(x.clientId)));const arr=[];for(const c of (state?.clients||[])){const pr=clientPriority(c),d=ds(getLast(c)),cy=getCycle(c),inc=alerts().filter(a=>String(a.id)===String(c.id));const urgent=inc.some(a=>a.waiting);if(pr.p==="P1"||pr.p==="P2"||ids.has(String(c.id))||urgent){arr.push({c,pr,d,cy,inc,due:due.filter(x=>String(x.clientId)===String(c.id)),urgent,score:(urgent?120:0)+(ids.has(String(c.id))?110:0)+pr.score})}}return arr.sort((a,b)=>b.score-a.score)}
function renderTodayMVP(){const box=document.getElementById("mvpToday");if(!box)return;const rows=buildToday(),due=dueActions(),urgent=rows.filter(x=>x.urgent).length,pageSize=20,totalPages=Math.max(1,Math.ceil(rows.length/pageSize));if(todayPage>=totalPages)todayPage=totalPages-1;if(todayPage<0)todayPage=0;const visible=rows.slice(todayPage*pageSize,(todayPage+1)*pageSize);box.querySelector(".mvpKpis").innerHTML=[["Para trabajar hoy",rows.length],["Acciones vencidas/hoy",due.length],["P1",rows.filter(x=>x.pr.p==="P1").length],["SKU esperando",urgent]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");box.querySelector(".mvpRows").innerHTML=visible.map(x=>{const last=getLast(x.c),next=x.cy&&last?new Date(new Date(last).getTime()+x.cy*86400000).toISOString().slice(0,10):"Sin patrón";const rec=x.inc[0];return `<tr data-client="${x.c.id}"><td><span class="v10badge ${x.pr.p==="P1"?"wait":x.pr.p==="P2"?"soon":"now"}">${x.pr.p}</span><br><b>${esc(clientName(x.c))}</b></td><td>${esc(x.pr.why)}${x.due.length?'<br><b class="overdue">Próxima acción pendiente</b>':""}</td><td>${last||"—"}<br><small>${x.d==null?"":x.d+" días"}</small></td><td>${x.cy?x.cy+" días":"Sin patrón"}<br><small>Esperada: ${next}</small></td><td>${rec?`<b>${esc(rec.sku)}</b><br><small>${esc(rec.product||"")} · ${rec.waiting?"CLIENTE ESPERANDO":"por llegar"}</small>`:"Revisar surtido BC > 30"}</td><td><button class="miniOpen" data-open="${x.c.id}">Gestionar</button></td></tr>`}).join("")||'<tr><td colspan="6">No hay acciones prioritarias para hoy.</td></tr>';const pg=box.querySelector(".todayPager");if(pg){pg.innerHTML=`<button class="soft prevPage" ${todayPage===0?"disabled":""}>‹ Anterior</button><span>Mostrando <b>${rows.length?todayPage*pageSize+1:0}–${Math.min((todayPage+1)*pageSize,rows.length)}</b> de <b>${rows.length}</b> · Página ${todayPage+1}/${totalPages}</span><button class="soft nextPage" ${todayPage>=totalPages-1?"disabled":""}>Siguiente ›</button>`;pg.querySelector(".prevPage").onclick=()=>{todayPage--;renderTodayMVP()};pg.querySelector(".nextPage").onclick=()=>{todayPage++;renderTodayMVP()}}box.querySelectorAll("[data-open]").forEach(b=>b.onclick=e=>{e.stopPropagation();const id=+b.dataset.open;if(typeof openClient==="function")openClient(id)})}
function addTodayMVP(){const hoy=document.getElementById("hoy");if(!hoy||document.getElementById("mvpToday"))return;const box=document.createElement("div");box.id="mvpToday";box.className="mvpToday";box.innerHTML='<div class="mvpTitle"><div><small>MVP OPERATIVO</small><h2>Mi Día · Qué trabajar hoy</h2><p>Prioriza recompra, acciones pendientes y clientes esperando mercadería.</p></div></div><div class="kpis mvpKpis"></div><div class="todayScroll"><table><thead><tr><th>Prioridad / cliente</th><th>Por qué hoy</th><th>Última compra</th><th>Ciclo / próxima</th><th>Qué revisar</th><th>Acción</th></tr></thead><tbody class="mvpRows"></tbody></table></div><div class="todayPager"></div>';hoy.prepend(box);renderTodayMVP()}
function injectPipeline360(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.pipeObserver)return;panel.dataset.pipeObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;if(detail.querySelector(".pipe360"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const p=pipeOf(c.id),box=document.createElement("div");box.className="pipe360";box.innerHTML=`<h3>Pipeline comercial</h3><p>Estado actual de esta oportunidad.</p><select class="pipeStageSel">${STAGES.map(st=>`<option ${st===p.stage?"selected":""}>${st}</option>`).join("")}</select><input class="pipeAmount" type="number" value="${p.amount||0}" placeholder="Monto si terminó en pedido"><button class="primary pipeSave">Actualizar etapa</button><div class="pipeHint"></div>`;detail.appendChild(box);box.querySelector(".pipeSave").onclick=()=>{const st=box.querySelector(".pipeStageSel").value,am=box.querySelector(".pipeAmount").value;setStage(c.id,st,am);box.querySelector(".pipeHint").textContent="Etapa actualizada: "+st}}).observe(panel,{childList:true,subtree:true})}
function injectNextAction(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.actionObserver)return;panel.dataset.actionObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;if(detail.querySelector(".nextActionBox"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const box=document.createElement("div");box.className="nextActionBox";box.innerHTML='<h3>Próxima acción</h3><p>Cada gestión debe terminar con un siguiente paso y una fecha.</p><select class="nextType"><option>Seguimiento</option><option>Enviar propuesta</option><option>Llamar</option><option>WhatsApp</option><option>Revisar stock</option><option>Confirmar pedido</option><option>Recompra</option></select><input class="nextDate" type="date"><input class="nextNote" placeholder="Detalle de la próxima acción"><button class="primary nextSave">Guardar próxima acción</button><div class="nextList"></div>';detail.appendChild(box);const draw=()=>{box.querySelector(".nextList").innerHTML=nextActions.filter(x=>String(x.clientId)===String(c.id)&&!x.done).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div><b>${esc(x.date)} · ${esc(x.type)}</b><span>${esc(x.note)}</span><button class="miniDone" data-id="${x.id}">Completar</button></div>`).join("")||"<small>Sin próxima acción pendiente.</small>";box.querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>{completeAction(b.dataset.id);draw()})};box.querySelector(".nextSave").onclick=()=>{addNextAction(c.id,box.querySelector(".nextType").value,box.querySelector(".nextDate").value,box.querySelector(".nextNote").value);box.querySelector(".nextNote").value="";draw()};draw()}).observe(panel,{childList:true,subtree:true})}
function addDataQuality(){const sec=document.getElementById("clientes")||document.querySelector('[data-panel="clientes"]');if(!sec||document.getElementById("dataQuality"))return;const cs=state?.clients||[];const confirmed=cs.filter(c=>(c.b2bConfirmedOrders||0)>0).length;const cycle=cs.filter(c=>getCycle(c)>0).length;const noEmail=cs.filter(c=>!c.email).length;const seen=new Set(),dupSet=new Set();cs.forEach(c=>{const e=norm(c.email);if(!e)return;if(seen.has(e))dupSet.add(e);else seen.add(e)});const dups=dupSet.size;const box=document.createElement("div");box.id="dataQuality";box.className="dataQuality";box.innerHTML=`<h3>Control de calidad de cartera</h3><div class="kpis"><div class="kpi"><span>Cuentas cartera</span><b>${cs.length}</b></div><div class="kpi"><span>Compradores confirmados</span><b>${confirmed}</b></div><div class="kpi"><span>Con ciclo calculado</span><b>${cycle}</b></div><div class="kpi"><span>Sin email</span><b>${noEmail}</b></div><div class="kpi"><span>Emails duplicados</span><b>${dups}</b></div></div><p>Los registros incompletos se mantienen visibles para revisión; no se eliminan automáticamente.</p>`;sec.prepend(box)}
function exportMvpBackup(){const payload={version:"V10-MVP",exportedAt:new Date().toISOString(),incoming,waiting,nextActions,pipeline};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="Yeppo_B2B_V10_MVP_Backup_"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function addBackupControls(){const hoy=document.getElementById("hoy");if(!hoy||document.getElementById("mvpBackup"))return;const box=document.createElement("div");box.id="mvpBackup";box.className="mvpBackup";box.innerHTML='<div><b>Respaldo del CRM</b><span>Descarga los datos manuales del MVP antes de cambios importantes.</span></div><button class="soft backupOut">Descargar backup</button>';hoy.appendChild(box);box.querySelector(".backupOut").onclick=exportMvpBackup}
function add360Summary(){const panel=document.getElementById("clientPanel")||document.querySelector(".drawer");if(!panel||panel.dataset.summaryObserver)return;panel.dataset.summaryObserver="1";new MutationObserver(()=>{const detail=document.getElementById("clientDetail")||panel;if(detail.querySelector(".summary360"))return;const email=[...detail.querySelectorAll("p,small,span,div")].map(x=>x.textContent).find(x=>/@/.test(x))||"";const c=(state?.clients||[]).find(x=>email.includes(x.email||""));if(!c)return;const pr=clientPriority(c),last=getLast(c),cy=getCycle(c),d=ds(last),next=cy&&last?new Date(new Date(last).getTime()+cy*86400000).toISOString().slice(0,10):"Sin patrón suficiente",pa=nextActions.filter(x=>String(x.clientId)===String(c.id)&&!x.done).sort((a,b)=>a.date.localeCompare(b.date))[0],inc=alerts().filter(x=>String(x.id)===String(c.id)),p=pipeOf(c.id),box=document.createElement("div");box.className="summary360";box.innerHTML=`<small>RESUMEN 360°</small><h3>${esc(clientName(c))}</h3><div class="summaryGrid"><div><span>Prioridad</span><b>${pr.p}</b><em>${esc(pr.why)}</em></div><div><span>Última compra</span><b>${last||"—"}</b><em>${d==null?"Sin dato":d+" días"}</em></div><div><span>Ciclo</span><b>${cy?cy+" días":"Sin patrón"}</b><em>Próxima: ${next}</em></div><div><span>Pipeline</span><b>${p.stage}</b><em>${p.amount?new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(p.amount):"Sin monto"}</em></div><div><span>Próxima acción</span><b>${pa?pa.date:"Sin tarea"}</b><em>${pa?esc(pa.type):"Programar seguimiento"}</em></div><div><span>Mercadería</span><b>${inc.length} alerta(s)</b><em>${inc.some(x=>x.waiting)?"Cliente esperando SKU":"Historial / llegada"}</em></div></div>`;detail.prepend(box)}).observe(panel,{childList:true,subtree:true})}
let aiVersion=0;
function aiClientContext(c){const last=getLast(c),cy=getCycle(c),d=ds(last),inc=alerts().filter(x=>String(x.id)===String(c.id)),wait=inc.filter(x=>x.waiting);return{last,cy,d,inc,wait,pr:clientPriority(c)}}
function aiScript(c,reason,version){const x=aiClientContext(c),name=(clientName(c)||"").split(" ")[0]||"Hola",sku=x.wait.slice(0,3).map(z=>z.product||z.sku).join(", "),incomingTxt=sku?`También vi que están próximos a ingresar ${sku}, que me habías consultado.`:"";const variants=[`Hola ${name}, ¿cómo estás? Te escribo para saber cómo les ha ido con los productos que llevaron la última vez y si hay algo en que podamos ayudarles con reposición o surtido. ${incomingTxt} Si te sirve, puedo revisar disponibilidad y dejarte algunas opciones sin compromiso.`,`Hola ${name}, espero que estés bien. Quería hacerte un seguimiento breve para saber cómo viene la rotación de los productos y si necesitan apoyo con alguna reposición. ${incomingTxt} Cuando tengas un momento me cuentas y lo revisamos.`,`Hola ${name}, ¿cómo va todo? Paso más que nada para saber cómo les está funcionando el surtido y si hay algún producto que estén buscando o que les esté faltando. ${incomingTxt} Si quieres, reviso lo que tenemos disponible y te comparto solo lo que pueda ser útil para ustedes.`,`Hola ${name}, ¿cómo estás? Quería consultar cómo han estado estas semanas y cómo se ha movido K-Beauty en tu tienda. ${incomingTxt} No es necesario que estén por comprar ahora; si hay algo que necesites revisar, feliz te ayudo con stock o alternativas.`];let msg=variants[version%variants.length];if(reason&&reason.trim())msg+=`\n\nNota para esta gestión: ${reason.trim()}`;return msg.replace(/\s+/g," ").trim()}
function addFriendlyAI(){if(document.getElementById("friendlyAI"))return;const panels=[...document.querySelectorAll(".panel")],sec=panels.find(p=>/asistente|guion|copilot/i.test(p.innerText||""));if(!sec)return;const box=document.createElement("div");box.id="friendlyAI";box.className="friendlyAI";const opts=(state?.clients||[]).map(c=>`<option value="${c.id}">${esc(clientName(c))}</option>`).join("");box.innerHTML=`<div class="aiHead"><small>ASISTENTE COMERCIAL</small><h2>Guion de contacto</h2><p>Mensajes consultivos, cercanos y sin presión de compra.</p></div><label>Cliente<select class="aiClient"><option value="">Selecciona cliente</option>${opts}</select></label><label>Contexto opcional<input class="aiReason" placeholder="Ej: preguntó por un producto, hace tiempo que no compra..."></label><div class="aiActions"><button class="primary aiGenerate">Generar guion</button><button class="soft aiAnother" disabled>Otra versión</button><button class="soft aiCopy" disabled>Copiar</button></div><textarea class="aiOutput" rows="8" placeholder="Aquí aparecerá el mensaje sugerido."></textarea><small class="aiRule">El objetivo es abrir conversación y ayudar. No presionar por una compra ni asumir que el cliente necesita reponer.</small>`;sec.prepend(box);const out=box.querySelector(".aiOutput"),gen=(another=false)=>{const id=box.querySelector(".aiClient").value,c=(state?.clients||[]).find(x=>String(x.id)===String(id));if(!c)return alert("Selecciona un cliente.");if(another)aiVersion++;else aiVersion=0;out.value=aiScript(c,box.querySelector(".aiReason").value,aiVersion);box.querySelector(".aiAnother").disabled=false;box.querySelector(".aiCopy").disabled=false};box.querySelector(".aiGenerate").onclick=()=>gen(false);box.querySelector(".aiAnother").onclick=()=>gen(true);box.querySelector(".aiCopy").onclick=async()=>{if(!out.value)return;try{await navigator.clipboard.writeText(out.value);box.querySelector(".aiCopy").textContent="Copiado";setTimeout(()=>box.querySelector(".aiCopy").textContent="Copiar",1200)}catch(e){out.select();document.execCommand("copy")}}}
function addAcademy(){const sec=document.getElementById("academia");if(!sec||sec.dataset.v10academy)return;sec.dataset.v10academy="1";const wrap=document.createElement("div");wrap.className="academyV10";wrap.innerHTML='<div class="academyHead"><h2>Academia Yeppo B2B</h2><p>Contenido práctico para que el cliente venda mejor, compre mejor y aumente su recompra.</p></div><div class="academyGrid">'+modules.map((m,i)=>`<article><small>Módulo ${i+1} · ${m[0]}</small><h3>${m[1]}</h3><b>${m[2]}</b><p>${m[3]}</p><span>Video corto · resumen · ejercicio · mini quiz · acción comercial</span></article>`).join("")+'</div>';sec.prepend(wrap)}
function addTodayAlert(refresh=false){const a=alerts(),urgent=a.filter(x=>x.waiting);if(refresh)document.getElementById("incomingToday")?.remove();if(!a.length)return;const host=document.querySelector("#hoy .sales-hero")||document.getElementById("hoy");if(!host||document.getElementById("incomingToday"))return;const d=document.createElement("div");d.id="incomingToday";d.className="incomingToday";d.innerHTML=`<small>Radar próximos ingresos</small><b>${urgent.length?urgent.length+" alertas PRIORITARIAS · ":""}${a.length} oportunidades por SKU en camino</b><span>${new Set(a.map(x=>x.id)).size} clientes relacionados</span>`;d.onclick=()=>document.querySelector('[data-tab="incoming"]')?.click();host.appendChild(d)}

async function accessHash(v){const buf=await crypto.subtle.digest("SHA-256",new TextEncoder().encode("YEPPO-V10|"+String(v)));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function setLocalAccess(code){localStorage.setItem(ACCESS_KEY,await accessHash(code))}
async function verifyLocalAccess(code){const h=localStorage.getItem(ACCESS_KEY);return !h||h===await accessHash(code)}
function addSecuritySettings(){if(document.getElementById("v10Security"))return;const tabs=document.querySelector(".tabs"),main=document.querySelector("main");if(!tabs||!main)return;const btn=document.createElement("button");btn.className="tab";btn.dataset.tab="v10security";btn.textContent="Configuración";tabs.appendChild(btn);const sec=document.createElement("section");sec.id="v10security";sec.className="panel";sec.innerHTML=`<div class="securityCard"><small>SEGURIDAD LOCAL</small><h2>Clave de acceso</h2><p>Cambia la clave adicional de esta V10 en este navegador. No modifica clientes, pipeline, acciones ni cargas.</p><label>Clave actual<input type="password" class="secCurrent" autocomplete="current-password"></label><label>Nueva clave<input type="password" class="secNew" autocomplete="new-password"></label><label>Repetir nueva clave<input type="password" class="secRepeat" autocomplete="new-password"></label><div class="securityActions"><button class="primary secSave">Cambiar clave</button></div><div class="secStatus"></div><div class="securityNote"><b>Importante:</b> esta protección es local al navegador. La clave de cifrado del archivo publicado en GitHub no se cambia desde la propia página.</div></div>`;main.appendChild(sec);btn.onclick=()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".panel").forEach(x=>x.classList.remove("active"));btn.classList.add("active");sec.classList.add("active")};sec.querySelector(".secSave").onclick=async()=>{const cur=sec.querySelector(".secCurrent").value,n=sec.querySelector(".secNew").value,r=sec.querySelector(".secRepeat").value,st=sec.querySelector(".secStatus");if(!n||n.length<6){st.textContent="La nueva clave debe tener al menos 6 caracteres.";return}if(n!==r){st.textContent="Las nuevas claves no coinciden.";return}if(!(await verifyLocalAccess(cur))){st.textContent="La clave actual no es correcta.";return}await setLocalAccess(n);sec.querySelectorAll("input").forEach(i=>i.value="");st.textContent="Clave local actualizada correctamente."}}

function moneyCLP(v){return new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(+v||0)}
function salesRows(){const out=[];const cs=state?.clients||[];for(const c of cs){const pools=[c.ordersHistory,c.orderHistory,c.pedidosHistorial,c.purchases,c.compras,c.orders];for(const p of pools){if(!Array.isArray(p))continue;for(const o of p){const date=o.date||o.fecha||o.createdAt||o.created_at||o.orderDate,amount=+(o.amount||o.total||o.venta||o.sales||o.monto||0);if(date&&amount)out.push({date:String(date).slice(0,10),amount})}}}return out}
function masterSales(){const rows=salesRows(),today=new Date(),iso=d=>d.toISOString().slice(0,10),td=iso(today),days=[];for(let i=6;i>=0;i--){const d=new Date(today);d.setDate(d.getDate()-i);const key=iso(d),value=rows.filter(x=>x.date===key).reduce((a,x)=>a+x.amount,0);days.push({key,label:d.toLocaleDateString("es-CL",{weekday:"short"}).replace(".",""),value})}const todayValue=days[6].value,week=days.reduce((a,x)=>a+x.value,0),max=Math.max(...days.map(x=>x.value),1);return{todayValue,week,days,max,hasData:rows.length>0}}

function crmIcon(name){const p={home:'M3 11.5 12 4l9 7.5M5 10v10h14V10M9 20v-6h6v6',day:'M5 3v3M19 3v3M4 8h16M5 5h14a1 1 0 0 1 1 1v14H4V6a1 1 0 0 1 1-1',kam:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',clients:'M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',products:'M21 16V8l-9-5-9 5v8l9 5 9-5ZM3.3 7.8 12 13l8.7-5.2M12 13v8',incoming:'M3 6h11v10H3zM14 10h4l3 3v3h-7zM7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4M18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',academy:'M3 10l9-5 9 5-9 5-9-5ZM7 12.5V17c3 2 7 2 10 0v-4.5',reports:'M4 20V10M10 20V4M16 20v-7M22 20V7',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1 .6l-.04.08H10l-.04-.08a1.7 1.7 0 0 0-1-.6 1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-.6-1l-.08-.04V10l.08-.04a1.7 1.7 0 0 0 .6-1 1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.83-2.83.06.06A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-.6l.04-.08h3.92l.04.08a1.7 1.7 0 0 0 1 .6 1.7 1.7 0 0 0 1.88-.34l.06-.06 2.83 2.83-.06.06A1.7 1.7 0 0 0 19.4 9c.17.38.38.72.6 1l.08.04v3.92L20 14a1.7 1.7 0 0 0-.6 1',tools:'M4 6h16M4 12h16M4 18h16'};return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(p[name]||p.tools)+'"/></svg>'}
const CRM_ROUTES={
 home:{data:['masterHome'],labels:['inicio']},
 day:{data:['hoy'],labels:['mi día','mi dia']},
 kam:{labels:['gestión kam','gestion kam','cartera / recompra','cartera/recompra']},
 clients:{labels:['base maestra','clientes']},
 products:{labels:['reposición sku','reposicion sku','productos']},
 incoming:{data:['incoming'],labels:['próximos ingresos','proximos ingresos']},
 academy:{data:['academia'],labels:['academia']},
 reports:{labels:['dashboard','reportes','top 20 general']},
 settings:{data:['v10security'],labels:['configuración','configuracion']}
};
function crmText(v){return String(v||'').trim().toLocaleLowerCase('es').replace(/\s+/g,' ')}
function crmLegacyTabs(){return [...document.querySelectorAll('.tabs .tab')].filter(x=>!x.classList.contains('crmNavBtn'))}
function crmFindRoute(key){const r=CRM_ROUTES[key]||{};const tabs=crmLegacyTabs();for(const d of r.data||[]){const t=tabs.find(x=>x.dataset.tab===d);if(t)return t}for(const l of r.labels||[]){const t=tabs.find(x=>crmText(x.textContent)===crmText(l)||crmText(x.textContent).includes(crmText(l)));if(t)return t}return null}
function crmSetNavActive(key){document.querySelectorAll('.crmNavBtn').forEach(x=>x.classList.toggle('active',x.dataset.route===key))}
function crmActivate(key,anchor){if(key==='home'){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById('masterHome')?.classList.add('active');document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));crmSetNavActive('home');window.scrollTo({top:0,behavior:'smooth'});return true}const t=crmFindRoute(key);if(!t)return false;t.click();crmSetNavActive(key);if(anchor)setTimeout(()=>document.getElementById(anchor)?.scrollIntoView({behavior:'smooth',block:'start'}),80);return true}
function crmBuildSidebar(){const tabs=document.querySelector('.tabs');if(!tabs||tabs.dataset.crmSidebar)return;tabs.dataset.crmSidebar='1';crmLegacyTabs().forEach(x=>x.classList.add('legacyTab'));const brand=document.createElement('div');brand.className='crmBrand';brand.innerHTML='<b>B2B <span>CRM</span></b><small>YEPPO · BELLEZA SIN LÍMITES</small>';const nav=document.createElement('div');nav.className='crmNav';const items=[['home','home','Inicio'],['day','day','Mi Día'],['kam','kam','Gestión KAM'],['clients','clients','Clientes'],['products','products','Productos'],['incoming','incoming','Próximos ingresos'],['academy','academy','Academia'],['reports','reports','Reportes'],['settings','settings','Configuración']];nav.innerHTML=items.map(([r,i,l])=>'<button class="crmNavBtn" data-route="'+r+'"><span class="crmNavIcon">'+crmIcon(i)+'</span><span>'+l+'</span></button>').join('');const foot=document.createElement('div');foot.className='crmSideFoot';foot.innerHTML='<button class="crmMore"><span class="crmNavIcon">'+crmIcon('tools')+'</span><span>Más herramientas</span></button><div class="crmTagline">Juntos hacemos crecer<br><b>la belleza</b></div>';tabs.prepend(brand,nav);tabs.append(foot);nav.querySelectorAll('.crmNavBtn').forEach(x=>x.onclick=()=>crmActivate(x.dataset.route));foot.querySelector('.crmMore').onclick=()=>crmOpenTools();crmSetNavActive('home')}
