function crmAuditNav(){const keys=['day','kam','clients','products','incoming','academy','reports','settings'];const missing=keys.filter(k=>!crmFindRoute(k));document.querySelectorAll('.crmNavBtn').forEach(b=>{const miss=missing.includes(b.dataset.route);b.disabled=miss;b.title=miss?'Módulo no disponible':''});document.documentElement.dataset.crmNavAudit=missing.length?'missing-'+missing.join('-'):'ok';return missing}

