function crmSalesChartV3(sales){const w=680,h=190,p=18,step=(w-p*2)/Math.max(1,sales.days.length-1),pts=sales.days.map((x,i)=>({x:p+i*step,y:h-p-(x.value/sales.max)*(h-p*2)})),line=pts.map(x=>`${x.x.toFixed(1)},${x.y.toFixed(1)}`).join(" "),area=`${p},${h-p} ${line} ${w-p},${h-p}`;return `<div class="crmLinePlotV3"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Ventas de los últimos siete días"><defs><linearGradient id="crmAreaV3" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ef3988" stop-opacity=".22"/><stop offset="100%" stop-color="#ef3988" stop-opacity=".02"/></linearGradient></defs><g class="grid">${[36,78,120,162].map(y=>`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}"/>`).join("")}</g><polygon points="${area}" fill="url(#crmAreaV3)"/><polyline points="${line}" fill="none" stroke="#ef3988" stroke-width="3" vector-effect="non-scaling-stroke"/>${pts.map((q,i)=>`<circle cx="${q.x}" cy="${q.y}" r="5" fill="#fff" stroke="#ef3988" stroke-width="3" vector-effect="non-scaling-stroke"><title>${sales.days[i].label}: ${moneyCLP(sales.days[i].value)}</title></circle>`).join("")}</svg><div class="crmChartLabelsV3">${sales.days.map(x=>`<span>${x.label}</span>`).join("")}</div></div>`}
